  ('spread_option1_option2_how_to_choose', $${"tr":{"title":"Seçenek 1 - Seçenek 2 - Nasıl Seçmeli","positions":[{"index":1,"title":"Seçenek 1","question":"Bu birinci seçeneğin vaat ettiği gerçeklik, ders ve gizli potansiyel nedir?"},{"index":2,"title":"Seçenek 2","question":"İkinci seçenek beni nereye götürür, hangi enerjiyi getirir ve hangi dinamikle yüzleşirim?"},{"index":3,"title":"Nasıl Seçmeli","question":"En yüksek iyiliğim için nihai kararı verirken yanılsamalardan arınmış rehberim ne olmalı?"}],"description":"Bir kavşakta zihinizi kaplayan sis perdesini kaldırarak doğru yönü aydınlatır.","layout_type":"horizontal"},"es":{"title":"Opción 1 - Opción 2 - Cómo elegir","description":"Levanta el velo de niebla que nubla tu mente en una encrucijada, iluminando la dirección correcta.","layout_type":"horizontal","positions":[{"index":1,"title":"Opción 1","question":"¿Cuál es la realidad, la lección y el potencial oculto que me promete esta primera opción?"},{"index":2,"title":"Opción 2","question":"¿Adónde me llevará esta segunda opción, qué energía me aportará y qué dinámica afrontaré?"},{"index":3,"title":"Cómo elegir","question":"Despojado de ilusiones, ¿cuál debería ser mi guía a la hora de tomar la decisión final para mi mayor bien?"}]},"pt":{"title":"Opção 1 - Opção 2 - Como Escolher","description":"Levanta o véu de neblina que nubla sua mente em uma encruzilhada, iluminando a direção certa.","layout_type":"horizontal","positions":[{"index":1,"title":"Opção 1","question":"Qual é a realidade, a lição e o potencial oculto que esta primeira opção me promete?"},{"index":2,"title":"Opção 2","question":"Aonde esta segunda opção me levará, que energia ela trará e que dinâmica enfrentarei?"},{"index":3,"title":"Como escolher","question":"Despojado de ilusões, qual deveria ser meu guia ao tomar a decisão final para o meu bem maior?"}]},"fr":{"title":"Option 1 - Option 2 - Comment choisir","description":"Lève le voile de brouillard qui obscurcit votre esprit à la croisée des chemins, éclairant la bonne direction.","layout_type":"horizontal","positions":[{"index":1,"title":"Option 1","question":"Quelle est la réalité, la leçon et le potentiel caché que me promet cette première option ?"},{"index":2,"title":"Option 2","question":"Où va me mener cette deuxième option, quelle énergie va-t-elle apporter et à quelle dynamique vais-je faire face ?"},{"index":3,"title":"Comment choisir","question":"Dépouillé d’illusions, quel devrait être mon guide pour prendre la décision ultime pour mon plus grand bien ?"}]},"de":{"title":"Option 1 – Option 2 – Auswahl","description":"Lüftet den Nebelschleier, der Ihren Geist an einer Kreuzung vernebelt, und zeigt Ihnen die richtige Richtung.","layout_type":"horizontal","positions":[{"index":1,"title":"Option 1","question":"Welche Realität, welche Lektion und welches verborgene Potenzial verspricht mir diese erste Option?"},{"index":2,"title":"Option 2","question":"Wohin wird mich diese zweite Option führen, welche Energie wird sie mit sich bringen und welche Dynamik wird auf mich zukommen?"},{"index":3,"title":"So wählen Sie aus","question":"Von welchen Illusionen befreit, was sollte mein Leitfaden sein, wenn ich die endgültige Entscheidung für mein höchstes Wohl treffe?"}]},"it":{"title":"Opzione 1 - Opzione 2 - Come scegliere","description":"Solleva il velo di nebbia che annebbia la tua mente ad un bivio, illuminando la giusta direzione.","layout_type":"horizontal","positions":[{"index":1,"title":"Opzione 1","question":"Qual è la realtà, la lezione e il potenziale nascosto che mi promette questa prima opzione?"},{"index":2,"title":"Opzione 2","question":"Dove mi porterà questa seconda opzione, quale energia porterà e quale dinamica dovrò affrontare?"},{"index":3,"title":"Come scegliere","question":"Privo di illusioni, quale dovrebbe essere la mia guida quando prendo la decisione finale per il mio bene supremo?"}]},"ja":{"title":"オプション 1 - オプション 2 - 選択方法","description":"交差点で心を曇らせる霧のベールを取り除き、正しい方向を照らしま