  ('spread_past_present_future', $${"tr":{"title":"Geçmiş - Şimdi - Gelecek","positions":[{"index":1,"title":"Geçmiş","question":"Bugünümü şekillendiren, geride bıraktığım kök enerji nedir?"},{"index":2,"title":"Şimdi","question":"Şu anda gerçekliğimi ve bu anın potansiyelini yöneten dinamikler nelerdir?"},{"index":3,"title":"Gelecek","question":"Mevcut yolculuğum beni nereye götürüyor ve hangi potansiyel gelecek bekliyor?"}],"description":"Hayatınızdaki olayların zaman çizelgesini ve birbirini nasıl etkilediğini aydınlatır.","layout_type":"horizontal"},"es":{"title":"Pasado - Presente - Futuro","description":"Ilumina la línea de tiempo de los acontecimientos de tu vida y cómo se influyen entre sí.","layout_type":"horizontal","positions":[{"index":1,"title":"Pasado","question":"¿Cuál es la energía raíz que he dejado atrás y que da forma a mi presente?"},{"index":2,"title":"presente","question":"¿Qué dinámicas gobiernan actualmente mi realidad y el potencial de este momento?"},{"index":3,"title":"Futuro","question":"¿Adónde me lleva mi viaje actual y qué futuro potencial me espera?"}]},"pt":{"title":"Passado - Presente - Futuro","description":"Ilumina a linha do tempo dos eventos em sua vida e como eles influenciam uns aos outros.","layout_type":"horizontal","positions":[{"index":1,"title":"Passado","question":"Qual é a energia raiz que deixei para trás e que molda o meu presente?"},{"index":2,"title":"Presente","question":"Que dinâmicas governam atualmente a minha realidade e o potencial deste momento?"},{"index":3,"title":"Futuro","question":"Para onde minha jornada atual está me levando e que futuro potencial me aguarda?"}]},"fr":{"title":"Passé - Présent - Futur","description":"Illumine la chronologie des événements de votre vie et la manière dont ils s'influencent mutuellement.","layout_type":"horizontal","positions":[{"index":1,"title":"Passé","question":"Quelle est l’énergie racine que j’ai laissée derrière moi et qui façonne mon présent ?"},{"index":2,"title":"Présent","question":"Quelles dynamiques régissent actuellement ma réalité et le potentiel de ce moment ?"},{"index":3,"title":"Avenir","question":"Où me mène mon voyage actuel et quel avenir potentiel m’attend ?"}]},"de":{"title":"Vergangenheit – Gegenwart – Zukunft","description":"Beleuchtet die zeitliche Abfolge von Ereignissen in Ihrem Leben und wie sie sich gegenseitig beeinflussen.","layout_type":"horizontal","positions":[{"index":1,"title":"Vergangenheit","question":"Welche Wurzelenergie, die ich zurückgelassen habe, prägt meine Gegenwart?"},{"index":2,"title":"Anwesend","question":"Welche Dynamiken bestimmen derzeit meine Realität und das Potenzial dieses Augenblicks?"},{"index":3,"title":"Zukunft","question":"Wohin führt mich meine aktuelle Reise und welche mögliche Zukunft erwartet mich?"}]},"it":{"title":"Passato - Presente - Futuro","description":"Illumina la cronologia degli eventi della tua vita e il modo in cui si influenzano a vicenda.","layout_type":"horizontal","positions":[{"index":1,"title":"Passato","question":"Qual è l'energia fondamentale che ho lasciato dietro di me e che modella il mio presente?"},{"index":2,"title":"Presente","question":"Quali dinamiche stanno attualmente governando la mia realtà e il potenziale di questo momento?"},{"index":3,"title":"Futuro","question":"Dove mi sta portando il mio viaggio attuale e quale potenziale futuro mi aspetta?"}]},"ja":{"title":"過去 - 現在 - 未来","description":"あなたの人生における出来事のタイムラインと、それらが互いにどのように影響を与えるかを明らかにします。","layout_type":"horizontal","positions":[{"index":1,"title":"過去","question":"私の今を形作る、私が残した根源的なエネルギーとは何でしょうか？"},{"index":2,"title":"プレゼント","question":"現在、私の現実とこの瞬間の可能性を支配している力学は何ですか?"},{"index":3,"title":"未来","question":"私の現在の旅は私をどこへ連れて行っているのでしょうか、そしてどのような潜在的な未来が待っているのでしょうか？"}]},"ko":{"title":"과거 - 현재 - 미래","description":"인생에서 일어나는 사건의 타임라인과 그것이 서로에게 어떤 영향을 미치는지 조명합니다.","layout_type":"horizontal","positions":[{"index":1,"title":"과거","question":"나의 현재를 형성하는, 내가 남긴 뿌리 에너지는 무엇입니까?"},{"index":2,"title":"현재","question":"현재 나의 현실과 이 순간의 잠재력을 지배하고 있는 역학은 무엇입니까?"},{"index":3,"title":"미래","question":"나의 현재 여행은 나를 어디로 데려가고 있으며, 어떤 미래가 기다리고 있습니까?"}]},"th":{"title":"อดีต-ปัจจุบัน-อนาคต","description":"ส่องสว่างไทม์ไลน์ของเหตุการณ์ในชีวิตของคุณและวิธีที่เหตุการณ์เหล่านั้นมีอิทธิพลต่อกัน","layout_type":"horizontal","positions":[{"index":1,"title":"อดีต","question":"อะไรคือพลังงานรากที่ฉันทิ้งไว้เบื้องหลังซึ่งกำหนดรูปแบบปัจจุบันของฉัน?"},{"index":2,"title":"ปัจจุบัน","question":"พลวัตใดที่ครอบงำความเป็นจริงและศักยภาพของฉันในขณะนี้?"},{"index":3,"title":"อนาคต","question":"การเดินทางในปัจจุบันของฉันจะพาฉันไปที่ไหน และอนาคตที่รออยู่คืออะไร?"}]},"zh-TW":{"title":"過去 - 現在 - 未來","description":"闡明你生活中事件的時間表以及它們如何相互影響。","layout_type":"horizontal","positions":[{"index":1,"title":"過去","question":"我留下來的塑造我現在的根本能量是什麼？"},{"index":2,"title":"現在","question":"目前哪些動力正在主導我的現實和此刻的潛力？"},{"index":3,"title":"未來","question":"我目前的旅程將帶我走向何方，潛在的未來在等著我？"}]},"ru":{"title":"Прошлое – Настоящее – Будущее","description":"Освещает хронологию событий в вашей жизни и то, как они влияют друг на друга.","layout_type":"horizontal","positions":[{"index":1,"title":"Прошлое","question":"Какая основная энергия, которую я оставил после себя, формирует мое настоящее?"},{"index":2,"title":"Настоящее время","question":"Какая динамика в настоящее время управляет моей реальностью и потенциалом этого момента?"},{"index":3,"title":"Будущее","question":"Куда ведет меня нынешний путь и какое потенциальное будущее меня ждет?"}]},"zh-CN":{"title":"过去 - 现在 - 未来","description":"阐明你生活中事件的时间表以及它们如何相互影响。","layout_type":"horizontal","positions":[{"index":1,"title":"过去","question":"我留下的塑造我现在的根本能量是什么？"},{"index":2,"title":"现在","question":"目前哪些动力正在主导我的现实和此刻的潜力？"},{"index":3,"title":"未来","question":"我当前的旅程将带我走向何方，潜在的未来在等待着我？"}]}}$$::jsonb),
  ('spread_mind_heart_soul', $${"tr":{"title":"Zihin - Kalp - Ruh","positions":[{"index":1,"title":"Zihin","question":"Zihnimin yarattığı yanılsamalar ya da sunduğu rasyonel gerçekler nelerdir?"},{"index":2,"title":"Kalp","question":"Beni yönlendiren, kalbimin derinlerinde yatan gerçek arzu nedir?"},{"index":3,"title":"Ruh","question":"Ruhumun bu deneyimden alması gereken temel ders ve ihtiyaç nedir?"}],"description":"İç bütünlüğe ulaşmanız için mantığı, duyguyu ve ruhsallığı dengeler.","layout_type":"horizontal"},"es":{"title":"Mente - Corazón - Alma","description":"Equilibra la lógica, las emociones y la espiritualidad para ayudarte a alcanzar la plenitud interior.","layout_type":"horizontal","positions":[{"index":1,"title":"Mente","question":"¿Qué ilusiones está creando mi mente o qué verdades racionales está presentando?"},{"index":2,"title":"corazón","question":"¿Cuál es el verdadero deseo que se encuentra en lo más profundo de mi corazón y que me guía?"},{"index":3,"title":"alma","question":"¿Cuál es la lección y necesidad fundamental que mi alma debe sacar de esta experiencia?"}]},"pt":{"title":"Mente - Coração - Alma","description":"Equilibra lógica, emoção e espiritualidade para ajudá-lo a alcançar a totalidade interior.","layout_type":"horizontal","positions":[{"index":1,"title":"Mente","question":"Que ilusões minha mente está criando ou que verdades racionais ela está apresentando?"},{"index":2,"title":"Coração","question":"Qual é o verdadeiro desejo que está no fundo do meu coração e que me guia?"},{"index":3,"title":"Alma","question":"Qual é a lição fundamental e a necessidade que minha alma deve tirar desta experiência?"}]},"fr":{"title":"Esprit - Coeur - Âme","description":"Équilibre la logique, l’émotion et la spiritualité pour vous aider à atteindre la plénitude intérieure.","layout_type":"horizontal","positions":[{"index":1,"title":"Esprit","question":"Quelles illusions mon esprit crée-t-il ou quelles vérités rationnelles présente-t-il ?"},{"index":2,"title":"Coeur","question":"Quel est le véritable désir qui me guide au plus profond de mon cœur ?"},{"index":3,"title":"Âme","question":"Quelle est la leçon fondamentale et le besoin que mon âme doit tirer de cette expérience ?"}]},"de":{"title":"Geist – Herz – Seele","description":"Bringt Logik, Emotion und Spiritualität in Einklang, um Ihnen zu helfen, innere Ganzheit zu erreichen.","layout_type":"horizontal","positions":[{"index":1,"title":"Geist","question":"Welche Illusionen erzeugt mein Verstand oder welche rationalen Wahrheiten präsentiert er?"},{"index":2,"title":"Herz","question":"Was ist der wahre Wunsch, der tief in meinem Herzen liegt und der mich leitet?"},{"index":3,"title":"Seele","question":"Was ist die grundlegende Lektion und das Bedürfnis, das meine Seele aus dieser Erfahrung ziehen muss?"}]},"it":{"title":"Mente - Cuore - Anima","description":"Bilancia logica, emozione e spiritualità per aiutarti a raggiungere la completezza interiore.","layout_type":"horizontal","positions":[{"index":1,"title":"Mente","question":"Quali illusioni sta creando la mia mente o quali verità razionali sta presentando?"},{"index":2,"title":"Cuore","question":"Qual è il vero desiderio che giace nel profondo del mio cuore e che mi guida?"},{"index":3,"title":"Anima","question":"Qual è la lezione fondamentale e il bisogno che la mia anima deve trarre da questa esperienza?"}]},"ja":{"title":"マインド - ハート - ソウル","description":"論理、感情、スピリチュアリティのバランスを整え、内なる全体性を達成するのに役立ちます。","layout_type":"horizontal","positions":[{"index":1,"title":"心","question":"私の心はどのような幻想を作り出しているのでしょうか、それともどのような合理的な真実を提示しているのでしょうか?"},{"index":2,"title":"ハート","question":"心の奥底に眠る、私を導く本当の願いとは何でしょうか？"},{"index":3,"title":"ソウル","question":"この経験から私の魂が学ばなければならない基本的な教訓と必要性は何ですか?"}]},"ko":{"title":"마음 - 마음 - 영혼","description":"논리, 감정, 영성의 균형을 유지하여 내면의 온전함을 달성하도록 돕습니다.","layout_type":"horizontal","positions":[{"index":1,"title":"마음","question":"내 마음은 어떤 환상을 만들어내고 있고, 어떤 합리적인 진실을 제시하고 있나요?"},{"index":2,"title":"하트","question":"내 마음 깊은 곳에 나를 인도하는 진정한 소망은 무엇인가?"},{"index":3,"title":"소울","question":"이 경험에서 내 영혼이 얻어야 할 근본적인 교훈과 필요는 무엇입니까?"}]},"th":{"title":"จิตใจ - หัวใจ - จิตวิญญาณ","description":"ปรับสมดุลตรรกะ อารมณ์ และจิตวิญญาณเพื่อช่วยให้คุณบรรลุความสมบูรณ์ภายใน","layout_type":"horizontal","positions":[{"index":1,"title":"ใจ","question":"จิตใจของฉันสร้างภาพลวงตาอะไร หรือมันนำเสนอความจริงที่มีเหตุผลอะไร?"},{"index":2,"title":"หัวใจ","question":"ความปรารถนาที่แท้จริงที่ซ่อนอยู่ลึกๆ ในใจฉันซึ่งนำทางฉันคืออะไร?"},{"index":3,"title":"โซล","question":"อะไรคือบทเรียนพื้นฐานและความต้องการของจิตวิญญาณของฉันที่ต้องนำมาจากประสบการณ์นี้"}]},"zh-TW":{"title":"頭腦 - 心 - 靈魂","description":"平衡邏輯、情感和靈性，幫助您實現內在的完整。","layout_type":"horizontal","positions":[{"index":1,"title":"心靈","question":"我的頭腦正在創造什麼幻象，或者它正在呈現什麼理性真理？"},{"index":2,"title":"心","question":"我內心深處引導我的真正願望是什麼？"},{"index":3,"title":"靈魂","question":"我的靈魂必須從這次經驗中汲取的基本教訓和需求是什麼？"}]},"ru":{"title":"Разум – Сердце – Душа","description":"Балансирует логику, эмоции и духовность, чтобы помочь вам достичь внутренней целостности.","layout_type":"horizontal","positions":[{"index":1,"title":"Разум","question":"Какие иллюзии создает мой разум или какие рациональные истины он представляет?"},{"index":2,"title":"Сердце","question":"Какое истинное желание лежит глубоко в моем сердце и направляет меня?"},{"index":3,"title":"Душа","question":"Какой фундаментальный урок и потребность моя душа должна извлечь из этого опыта?"}]},"zh-CN":{"title":"头脑 - 心 - 灵魂","description":"平衡逻辑、情感和灵性，帮助您实现内在的完整。","layout_type":"horizontal","positions":[{"index":1,"title":"心灵","question":"我的头脑正在创造什么幻象，或者它正在呈现什么理性真理？"},{"index":2,"title":"心","question":"我内心深处引导我的真正愿望是什么？"},{"index":3,"title":"灵魂","question":"我的灵魂必须从这次经历中汲取的基本教训和需要是什么？"}]}}$$::jsonb),
  ('spread_problem_action_avoid', $${"tr":{"title":"Sorun - Eylem - Kaçın","positions":[{"index":1,"title":"Sorun","question":"Yüzleşmem gereken sorunun görünmeyen kök nedeni nedir?"},{"index":2,"title":"Eylem","question":"Çözüm bulmak ve ilerlemek için şu an atmam gereken en doğru adım nedir?"},{"index":3,"title":"Kaçın","question":"Süreci sabote etmemek için uzak durmam gereken eylem veya enerji nedir?"}],"description":"Çıkmaz sokaklarla karşılaştığınızda net bir eylem planı çizmenize yardımcı olan stratejik rehberlik sunar.","layout_type":"horizontal"},"es":{"title":"Problema - Acción - Evitar","description":"Ofrece orientación estratégica para ayudarle a trazar un plan de acción claro cuando se enfrente a callejones sin salida.","layout_type":"horizontal","positions":[{"index":1,"title":"problema","question":"¿Cuál es la causa raíz invisible del problema que debo enfrentar?"},{"index":2,"title":"acción","question":"¿Cuál es el paso más preciso que debo dar ahora mismo para encontrar una solución y seguir adelante?"},{"index":3,"title":"evitar","question":"¿De qué acción o energía debo alejarme para no sabotear el proceso?"}]},"pt":{"title":"Problema - Ação - Evitar","description":"Oferece orientação estratégica para ajudá-lo a traçar um plano de ação claro ao enfrentar becos sem saída.","layout_type":"horizontal","positions":[{"index":1,"title":"Problema","question":"Qual é a causa raiz invisível do problema que devo enfrentar?"},{"index":2,"title":"Ação","question":"Qual é o passo mais preciso que preciso dar agora para encontrar uma solução e seguir em frente?"},{"index":3,"title":"Evite","question":"De qual ação ou energia devo me afastar para evitar sabotar o processo?"}]},"fr":{"title":"Problème – Action – Éviter","description":"Offre des conseils stratégiques pour vous aider à élaborer un plan d’action clair lorsque vous faites face à des impasses.","layout_type":"horizontal","positions":[{"index":1,"title":"Problème","question":"Quelle est la cause profonde invisible du problème auquel je dois faire face ?"},{"index":2,"title":"Action","question":"Quelle est l’étape la plus précise que je dois suivre maintenant pour trouver une solution et aller de l’avant ?"},{"index":3,"title":"Éviter","question":"De quelle action ou énergie dois-je rester à l’écart pour éviter de saboter le processus ?"}]},"de":{"title":"Problem – Aktion – Vermeiden","description":"Bietet strategische Anleitung, die Ihnen hilft, einen klaren Aktionsplan zu erstellen, wenn Sie in Sackgassen geraten.","layout_type":"horizontal","positions":[{"index":1,"title":"Problem","question":"Was ist die unsichtbare Ursache des Problems, mit dem ich konfrontiert bin?"},{"index":2,"title":"Aktion","question":"Was ist der genaueste Schritt, den ich jetzt unternehmen muss, um eine Lösung zu finden und voranzukommen?"},{"index":3,"title":"Vermeiden","question":"Von welcher Aktion oder Energie muss ich Abstand halten, um eine Sabotage des Prozesses zu vermeiden?"}]},"it":{"title":"Problema - Azione - Evitare","description":"Offre una guida strategica per aiutarti a tracciare un piano d'azione chiaro quando affronti vicoli ciechi.","layout_type":"horizontal","positions":[{"index":1,"title":"Problema","question":"Qual è la causa principale invisibile del problema che devo affrontare?"},{"index":2,"title":"Azione","question":"Qual è il passo più preciso che devo compiere in questo momento per trovare una soluzione e andare avanti?"},{"index":3,"title":"Evitare","question":"Da quale azione o energia devo stare lontano per evitare di sabotare il processo?"}]},"ja":{"title":"問題 - アクション - 回避","description":"行き詰まりに直面したときに明確な行動計画を立てるのに役立つ戦略的ガイダンスを提供します。","layout_type":"horizontal","positions":[{"index":1,"title":"問題","question":"私が直面しなければならない問題の見えない根本原因は何ですか?"},{"index":2,"title":"アクション","question":"解決策を見つけて先に進むために、今実行する必要がある最も正確な手順は何ですか?"},{"index":3,"title":"避ける","question":"プロセスの妨害を避けるために、どの行動やエネルギーを避けなければなりませんか?"}]},"ko":{"title":"문제 - 조치 - 회피","description":"막다른 골목에 직면했을 때 명확한 실행 계획을 세우는 데 도움이 되는 전략적 지침을 제공합니다.","layout_type":"horizontal","positions":[{"index":1,"title":"문제","question":"내가 직면해야 할 문제의 보이지 않는 근본 원인은 무엇인가?"},{"index":2,"title":"액션","question":"해결책을 찾고 앞으로 나아가기 위해 지금 당장 취해야 할 가장 정확한 단계는 무엇입니까?"},{"index":3,"title":"피하다","question":"프로세스를 방해하지 않으려면 어떤 행동이나 에너지를 피해야 합니까?"}]},"th":{"title":"ปัญหา - การกระทำ - หลีกเลี่ยง","description":"เสนอคำแนะนำเชิงกลยุทธ์เพื่อช่วยคุณวาดแผนปฏิบัติการที่ชัดเจนเมื่อเผชิญกับทางตัน","layout_type":"horizontal","positions":[{"index":1,"title":"ปัญหา","question":"อะไรคือต้นตอของปัญหาที่มองไม่เห็นที่ฉันจะต้องเผชิญ?"},{"index":2,"title":"การดำเนินการ","question":"ขั้นตอนที่แม่นยำที่สุดที่ฉันต้องทำตอนนี้เพื่อค้นหาวิธีแก้ไขและก้าวไปข้างหน้าคืออะไร"},{"index":3,"title":"หลีกเลี่ยง","question":"ฉันจะต้องหลีกเลี่ยงการกระทำหรือพลังงานใดเพื่อหลีกเลี่ยงการก่อวินาศกรรมกระบวนการนี้"}]},"zh-TW":{"title":"問題 - 行動 - 避免","description":"提供策略指導，幫助您在面臨死胡同時制定清晰的行動計劃。","layout_type":"horizontal","positions":[{"index":1,"title":"問題","question":"我必須面對的問題的看不見的根本原因是什麼？"},{"index":2,"title":"行動","question":"為了找到解決方案並繼續前進，我現在需要採取的最準確的步驟是什麼？"},{"index":3,"title":"避免","question":"我必須遠離哪些行為或能量以避免破壞這個過程？"}]},"ru":{"title":"Проблема – Действие – Избежать","description":"Предлагает стратегическое руководство, которое поможет вам составить четкий план действий, если вы столкнетесь с тупиком.","layout_type":"horizontal","positions":[{"index":1,"title":"Проблема","question":"Какова невидимая первопричина проблемы, с которой мне предстоит столкнуться?"},{"index":2,"title":"Действие","question":"Какой наиболее точный шаг мне нужно предпринять прямо сейчас, чтобы найти решение и двигаться вперед?"},{"index":3,"title":"Избегайте","question":"От какого действия или энергии мне следует держаться подальше, чтобы не саботировать процесс?"}]},"zh-CN":{"title":"问题 - 行动 - 避免","description":"提供战略指导，帮助您在面临死胡同时制定清晰的行动计划。","layout_type":"horizontal","positions":[{"index":1,"title":"问题","question":"我必须面对的问题的看不见的根本原因是什么？"},{"index":2,"title":"行动","question":"为了找到解决方案并继续前进，我现在需要采取的最准确的步骤是什么？"},{"index":3,"title":"避免","question":"我必须远离哪些行为或能量以避免破坏该过程？"}]}}$$::jsonb),
  ('spread_red_green_yellow_light', $${"tr":{"title":"Kırmızı Işık - Yeşil Işık - Sarı Işık","positions":[{"index":1,"title":"Kırmızı Işık","question":"Israr etmeyi bırakmam, derhal durdurmam veya uzaklaşmam gereken tehlike nedir?"},{"index":2,"title":"Yeşil Işık","question":"Evrenin beni desteklediği ve cesaretle ilerlemememi gerektiren alan nedir?"},{"index":3,"title":"Sarı Işık","question":"Dikkatli yaklaşmamı, gözlemlemi ve zamanın akışına bırakmamı gerektiren durum nedir?"}],"description":"Hayatın kavşaklarında nerede hızlanmanız, nerede durmanız gerektiğini netleştirir.","layout_type":"horizontal"},"es":{"title":"Luz Roja - Luz Verde - Luz Amarilla","description":"Aclara en qué áreas de las encrucijadas de la vida necesitas acelerar y en cuáles debes reducir la velocidad.","layout_type":"horizontal","positions":[{"index":1,"title":"Luz roja","question":"¿En qué peligro debo dejar de insistir, detenerme inmediatamente o alejarme?"},{"index":2,"title":"Luz verde","question":"¿En qué área me apoya el universo y me exige que dé un paso adelante y acelere con valentía?"},{"index":3,"title":"Luz amarilla","question":"¿Qué situación requiere que me acerque con cautela, observe y deje que el tiempo siga su curso?"}]},"pt":{"title":"Luz Vermelha - Luz Verde - Luz Amarela","description":"Esclarece em quais áreas das encruzilhadas da vida você precisa acelerar e em quais você deve desacelerar.","layout_type":"horizontal","positions":[{"index":1,"title":"Luz Vermelha","question":"Em que perigo devo parar de insistir, parar imediatamente ou fugir?"},{"index":2,"title":"Luz Verde","question":"Em que área o universo está me apoiando, exigindo que eu avance e acelere com ousadia?"},{"index":3,"title":"Luz Amarela","question":"Que situação exige que eu aborde com cautela, observe e deixe o tempo seguir seu curso?"}]},"fr":{"title":"Feu rouge - Feu vert - Feu jaune","description":"Clarifie dans quels domaines du carrefour de la vie vous devez accélérer et dans lesquels vous devez ralentir.","layout_type":"horizontal","positions":[{"index":1,"title":"Lumière rouge","question":"Sur quel danger dois-je cesser d’insister, m’arrêter immédiatement ou m’éloigner ?"},{"index":2,"title":"Feu vert","question":"Dans quel domaine l’univers me soutient-il, m’obligeant à avancer et à accélérer avec audace ?"},{"index":3,"title":"Lumière jaune","question":"Quelle situation m’oblige à aborder avec prudence, observer et laisser le temps suivre son cours ?"}]},"de":{"title":"Rotes Licht – grünes Licht – gelbes Licht","description":"Klärt, in welchen kritischen Bereichen des Lebens Sie Gas geben und in welchen Sie Ihr Tempo drosseln müssen.","layout_type":"horizontal","positions":[{"index":1,"title":"Rotes Licht","question":"Vor welcher Gefahr muss ich aufhören, darauf zu beharren, sofort aufhören oder davonlaufen?"},{"index":2,"title":"Grünes Licht","question":"In welchem Bereich unterstützt mich das Universum und verlangt von mir, mutig voranzugehen und Gas zu geben?"},{"index":3,"title":"Gelbes Licht","question":"Welche Situation erfordert von mir, vorsichtig anzugehen, zu beobachten und der Zeit ihren Lauf zu lassen?"}]},"it":{"title":"Luce rossa - Luce verde - Luce gialla","description":"Chiarisce in quali aree dei bivi della vita è necessario accelerare e in quali è necessario rallentare.","layout_type":"horizontal","positions":[{"index":1,"title":"Luce rossa","question":"Su quale pericolo devo smettere di insistere, fermarmi immediatamente o allontanarmi?"},{"index":2,"title":"Luce verde","question":"In quale area l’universo mi supporta, richiedendomi di fare coraggiosamente un passo avanti e accelerare?"},{"index":3,"title":"Luce gialla","question":"Quale situazione mi richiede di avvicinarmi con cautela, osservare e lasciare che il tempo faccia il suo corso?"}]},"ja":{"title":"赤色光 - 緑色光 - 黄色光","description":"人生の岐路のどの領域でスピードを上げる必要があり、どの領域で減速する必要があるかを明確にします。","layout_type":"horizontal","positions":[{"index":1,"title":"赤信号","question":"どのような危険について、主張するのをやめたり、すぐに停止したり、立ち去ったりしなければなりませんか?"},{"index":2,"title":"グリーンライト","question":"宇宙はどの領域で私をサポートし、私に大胆に前進し、加速することを求めているのでしょうか？"},{"index":3,"title":"イエローライト","question":"慎重に対処し、観察し、時間の経過に任せる必要があるのはどのような状況ですか?"}]},"ko":{"title":"빨간불 - 녹색불 - 노란불","description":"인생의 교차로에서 속도를 높여야 하는 영역과 속도를 줄여야 하는 영역을 명확히 합니다.","layout_type":"horizontal","positions":[{"index":1,"title":"빨간불","question":"어떤 위험에 대해 고집을 멈추고, 즉시 멈추고, 떠나야 합니까?"},{"index":2,"title":"초록불","question":"우주는 어떤 영역에서 나를 지탱하고, 나에게 과감하게 전진하고 가속하도록 요구하는가?"},{"index":3,"title":"노란불","question":"어떤 상황에서 주의 깊게 접근하고, 관찰하고, 시간이 흐르도록 놔두어야 합니까?"}]},"th":{"title":"ไฟแดง - ไฟเขียว - ไฟเหลือง","description":"ชี้แจงให้ชัดเจนว่าทางแยกของชีวิตบริเวณใดที่คุณต้องเร่งความเร็วและทางใดที่คุณต้องชะลอความเร็ว","layout_type":"horizontal","positions":[{"index":1,"title":"ไฟแดง","question":"อันตรายอะไรที่ฉันจะต้องหยุดยืนกราน หยุดทันที หรือเดินหนี?"},{"index":2,"title":"ไฟเขียว","question":"จักรวาลสนับสนุนฉันในด้านใด โดยกำหนดให้ฉันต้องก้าวไปข้างหน้าอย่างกล้าหาญและเร่งความเร็ว?"},{"index":3,"title":"แสงสีเหลือง","question":"สถานการณ์ใดที่ฉันต้องเข้าใกล้ด้วยความระมัดระวัง สังเกต และปล่อยให้เวลาผ่านไป?"}]},"zh-TW":{"title":"紅燈 - 綠燈 - 黃燈","description":"明確在人生十字路口的哪些方面你需要加快速度，哪些方面你必須放慢速度。","layout_type":"horizontal","positions":[{"index":1,"title":"紅燈","question":"有什麼危險我必須停止堅持、立即停止或遠離？"},{"index":2,"title":"綠燈","question":"宇宙在哪些方面支持我，需要我大膽前進、加速前進？"},{"index":3,"title":"黃燈","question":"什麼情況需要我謹慎對待、觀察、順其自然？"}]},"ru":{"title":"Красный свет - Зеленый свет - Желтый свет","description":"Уточняет, на каких участках жизненных перекрестков нужно ускориться, а на каких следует замедлиться.","layout_type":"horizontal","positions":[{"index":1,"title":"Красный свет","question":"О какой опасности я должен перестать настаивать, немедленно остановиться или уйти от нее?"},{"index":2,"title":"Зеленый свет","question":"В какой области Вселенная поддерживает меня, требуя смело шагнуть вперед и ускориться?"},{"index":3,"title":"Желтый свет","question":"Какая ситуация требует от меня подхода с осторожностью, наблюдения и предоставления времени идти своим чередом?"}]},"zh-CN":{"title":"红灯 - 绿灯 - 黄灯","description":"明确在人生十字路口的哪些方面你需要加快速度，哪些方面你必须放慢速度。","layout_type":"horizontal","positions":[{"index":1,"title":"红灯","question":"有什么危险我必须停止坚持、立即停止或远离？"},{"index":2,"title":"绿灯","question":"宇宙在哪些方面支持着我，需要我大胆前行、加速前进？"},{"index":3,"title":"黄灯","question":"什么情况需要我谨慎对待、观察、顺其自然？"}]}}$$::jsonb),
  ('spread_desire_conflict_resolution', $${"tr":{"title":"Arzu - Çatışma - Çözüm","positions":[{"index":1,"title":"Arzu","question":"Egonun ötesinde, kalbim ve ruhum gerçekten ne istiyor?"},{"index":2,"title":"Çatışma","question":"Bu arzuyu geciktiren iç direncim veya dış dünyadaki ana çatışma nedir?"},{"index":3,"title":"Çözüm","question":"Çatışmayı sona erdirmek ve arzumu gerçeğe dönüştürmek için ne yapmalıyım?"}],"description":"İç çatışmalarınızı ve tutkularınızı gün yüzüne çıkararak hedeflerinize giden yoldaki engelleri düzleştirir.","layout_type":"horizontal"},"es":{"title":"Deseo - Conflicto - Resolución","description":"Saca a la superficie tus conflictos internos y pasiones para suavizar los obstáculos en el camino hacia tus metas.","layout_type":"horizontal","positions":[{"index":1,"title":"deseo","question":"Más allá de mi ego, ¿cuál es la verdadera meta que mi corazón y mi alma realmente desean?"},{"index":2,"title":"Conflicto","question":"¿Cuál es mi resistencia interior o el principal conflicto en el mundo exterior que retrasa este deseo?"},{"index":3,"title":"Resolución","question":"¿Qué acción debo tomar para poner fin al conflicto y convertir mi deseo en realidad?"}]},"pt":{"title":"Desejo - Conflito - Resolução","description":"Revele seus conflitos e paixões internas para suavizar os obstáculos no caminho para seus objetivos.","layout_type":"horizontal","positions":[{"index":1,"title":"Desejo","question":"Além do meu ego, qual é o verdadeiro objetivo que meu coração e minha alma desejam genuinamente?"},{"index":2,"title":"Conflito","question":"Qual é a minha resistência interior ou o principal conflito no mundo exterior que atrasa esse desejo?"},{"index":3,"title":"Resolução","question":"Que ações preciso tomar para acabar com o conflito e transformar meu desejo em realidade?"}]},"fr":{"title":"Désir - Conflit - Résolution","description":"Fait ressortir vos conflits intérieurs et vos passions pour aplanir les obstacles sur la route de vos objectifs.","layout_type":"horizontal","positions":[{"index":1,"title":"Désir","question":"Au-delà de mon ego, quel est le véritable objectif que mon cœur et mon âme désirent réellement ?"},{"index":2,"title":"Conflit","question":"Quelle est ma résistance intérieure ou le principal conflit dans le monde extérieur qui retarde ce désir ?"},{"index":3,"title":"Résolution","question":"Quelle action dois-je entreprendre pour mettre fin au conflit et transformer mon désir en réalité ?"}]},"de":{"title":"Wunsch – Konflikt – Lösung","description":"Bringen Sie Ihre inneren Konflikte und Leidenschaften zum Vorschein, um die Unebenheiten auf dem Weg zu Ihren Zielen auszugleichen.","layout_type":"horizontal","positions":[{"index":1,"title":"Wunsch","question":"Was ist über mein Ego hinaus das wahre Ziel, das sich mein Herz und meine Seele wirklich wünschen?"},{"index":2,"title":"Konflikt","question":"Was ist mein innerer Widerstand oder der Hauptkonflikt in der Außenwelt, der diesen Wunsch verzögert?"},{"index":3,"title":"Auflösung","question":"Welche Maßnahmen muss ich ergreifen, um den Konflikt zu beenden und meinen Wunsch in die Realität umzusetzen?"}]},"it":{"title":"Desiderio - Conflitto - Risoluzione","description":"Fa emergere i tuoi conflitti interiori e le tue passioni per appianare gli ostacoli sulla strada verso i tuoi obiettivi.","layout_type":"horizontal","positions":[{"index":1,"title":"Desiderio","question":"Al di là del mio ego, qual è il vero obiettivo che il mio cuore e la mia anima desiderano sinceramente?"},{"index":2,"title":"Conflitto","question":"Qual è la mia resistenza interiore o il principale conflitto nel mondo esterno che ritarda questo desiderio?"},{"index":3,"title":"Risoluzione","question":"Quale azione devo intraprendere per porre fine al conflitto e trasformare il mio desiderio in realtà?"}]},"ja":{"title":"欲望 - 葛藤 - 解決","description":"あなたの内面の葛藤や情熱を表面化し、目標への道の凹凸を滑らかにします。","layout_type":"horizontal","positions":[{"index":1,"title":"欲望","question":"私のエゴを超えて、私の心と魂が心から望む真の目標は何でしょうか？"},{"index":2,"title":"紛争","question":"この願望を遅らせている私の内なる抵抗、あるいは外界の主な葛藤は何でしょうか?"},{"index":3,"title":"解像度","question":"紛争を終わらせ、私の願望を現実にするためには、どのような行動を取る必要がありますか?"}]},"ko":{"title":"욕망 - 갈등 - 해결","description":"내면의 갈등과 열정을 표면화하여 목표를 향한 길의 장애물을 완화합니다.","layout_type":"horizontal","positions":[{"index":1,"title":"욕망","question":"나의 자아를 넘어, 내 마음과 영혼이 진심으로 원하는 진정한 목표는 무엇입니까?"},{"index":2,"title":"갈등","question":"이 욕망을 지연시키는 나의 내면의 저항이나 외부 세계의 주요 갈등은 무엇입니까?"},{"index":3,"title":"해상도","question":"갈등을 끝내고 나의 소망을 현실로 바꾸려면 어떤 조치를 취해야 합니까?"}]},"th":{"title":"ความปรารถนา - ความขัดแย้ง - ความละเอียด","description":"เผยให้เห็นความขัดแย้งและความหลงใหลภายในของคุณเพื่อขจัดปัญหาบนท้องถนนไปสู่เป้าหมายของคุณ","layout_type":"horizontal","positions":[{"index":1,"title":"ความปรารถนา","question":"นอกเหนือจากอัตตาของฉันแล้ว อะไรคือเป้าหมายที่แท้จริงที่หัวใจและจิตวิญญาณของฉันต้องการอย่างแท้จริง?"},{"index":2,"title":"ความขัดแย้ง","question":"การต่อต้านภายในของฉันหรือความขัดแย้งหลักในโลกภายนอกคืออะไรที่ทำให้ความปรารถนานี้ล่าช้า?"},{"index":3,"title":"ความละเอียด","question":"ฉันต้องดำเนินการอย่างไรเพื่อยุติความขัดแย้งและเปลี่ยนความปรารถนาให้เป็นจริง?"}]},"zh-TW":{"title":"慾望 - 衝突 - 解決","description":"展現你內心的衝突和熱情，以消除實現目標之路的坎坷。","layout_type":"horizontal","positions":[{"index":1,"title":"慾望","question":"除了我的自我之外，我的內心和靈魂真正渴望的真正目標是什麼？"},{"index":2,"title":"衝突","question":"我內心的阻力或外在世界的主要衝突是什麼延遲了這個願望？"},{"index":3,"title":"解析度","question":"我需要採取什麼行動來結束衝突並將我的願望變成現實？"}]},"ru":{"title":"Желание – Конфликт – Разрешение","description":"Выявляет ваши внутренние конфликты и страсти, чтобы сгладить неровности на пути к вашим целям.","layout_type":"horizontal","positions":[{"index":1,"title":"Желание","question":"Помимо моего эго, какова истинная цель, которую искренне желают мои сердце и душа?"},{"index":2,"title":"Конфликт","question":"Что является моим внутренним сопротивлением или основным конфликтом во внешнем мире, задерживающим это желание?"},{"index":3,"title":"Разрешение","question":"Какие действия мне нужно предпринять, чтобы положить конец конфликту и воплотить свое желание в реальность?"}]},"zh-CN":{"title":"欲望 - 冲突 - 解决","description":"展现你内心的冲突和激情，以消除实现目标道路上的坎坷。","layout_type":"horizontal","positions":[{"index":1,"title":"欲望","question":"除了我的自我之外，我的内心和灵魂真正渴望的真正目标是什么？"},{"index":2,"title":"冲突","question":"我内心的阻力或外部世界的主要冲突是什么延迟了这个愿望？"},{"index":3,"title":"分辨率","question":"我需要采取什么行动来结束冲突并将我的愿望变成现实？"}]}}$$::jsonb),
  ('spread_let_go_embrace_hold', $${"tr":{"title":"Bırak - Kucakla - Tut","positions":[{"index":1,"title":"Bırak","question":"Artık bana hizmet etmeyen, beni ağırlaştıran ve bırakmam gereken duygu nedir?"},{"index":2,"title":"Kucakla","question":"Evrenin sunduğu ve hayatıma entegre etmeye açık olmam gereken hediye nedir?"},{"index":3,"title":"Tut","question":"Ne olursa olsun korumam, tutunmam ve şükretmem gereken temel değer nedir?"}],"description":"Yüklerinizi hafifletmek ve doğru enerjilere yer açmak için ruhsal bir envanter çıkarır.","layout_type":"horizontal"},"es":{"title":"Soltar - Abrazar - Sostener","description":"Haz un inventario espiritual para aligerar tus cargas y hacer espacio para las energías adecuadas.","layout_type":"horizontal","positions":[{"index":1,"title":"dejar ir","question":"¿Qué sentimiento ya no me sirve, me pesa y necesita ser liberado?"},{"index":2,"title":"abrazar","question":"¿Qué regalo me ofrece el universo que debo estar abierto a aceptar e integrar en mi vida?"},{"index":3,"title":"Espera","question":"¿Qué valor fundamental debo proteger, conservar y agradecer pase lo que pase?"}]},"pt":{"title":"Deixe ir - abrace - segure","description":"Faz um inventário espiritual para aliviar seus fardos e abrir espaço para as energias certas.","layout_type":"horizontal","positions":[{"index":1,"title":"Deixe ir","question":"Que sentimento não me serve mais, me pesa e precisa ser liberado?"},{"index":2,"title":"Abraçar","question":"Que presente o universo está oferecendo que devo estar aberto para aceitar e integrar em minha vida?"},{"index":3,"title":"Espera","question":"Que valor fundamental devo proteger, agarrar e ser grato, não importa o que aconteça?"}]},"fr":{"title":"Lâcher prise - Embrasser - Tenir","description":"Fait un inventaire spirituel pour alléger vos fardeaux et faire de la place aux bonnes énergies.","layout_type":"horizontal","positions":[{"index":1,"title":"Lâcher prise","question":"Quel sentiment ne me sert plus, m'alourdit et doit être libéré ?"},{"index":2,"title":"Embrasser","question":"Quel cadeau l’univers m’offre-t-il que je dois être ouvert à accepter et à intégrer dans ma vie ?"},{"index":3,"title":"Tenir","question":"Quelle valeur fondamentale dois-je protéger, conserver et pour laquelle je suis reconnaissant quoi qu’il arrive ?"}]},"de":{"title":"Loslassen – Umarmen – Halten","description":"Führt eine spirituelle Bestandsaufnahme durch, um Ihre Lasten zu erleichtern und Platz für die richtigen Energien zu schaffen.","layout_type":"horizontal","positions":[{"index":1,"title":"Lass los","question":"Welches Gefühl dient mir nicht mehr, belastet mich und muss losgelassen werden?"},{"index":2,"title":"Umarmen","question":"Welches Geschenk bietet das Universum, das ich annehmen und in mein Leben integrieren muss?"},{"index":3,"title":"Halt","question":"Welchen Grundwert muss ich schützen, an dem ich festhalten und für den ich dankbar sein muss, egal was passiert?"}]},"it":{"title":"Lascia andare - Abbraccia - Tieni","description":"Fa un inventario spirituale per alleggerire i tuoi fardelli e fare spazio alle giuste energie.","layout_type":"horizontal","positions":[{"index":1,"title":"Lascia andare","question":"Quale sentimento non mi serve più, mi appesantisce e ha bisogno di essere rilasciato?"},{"index":2,"title":"Abbraccio","question":"Quale dono mi offre l'universo che devo essere aperto ad accettare e integrare nella mia vita?"},{"index":3,"title":"Tieni","question":"Quale valore fondamentale devo proteggere, mantenere ed essere grato, qualunque cosa accada?"}]},"ja":{"title":"手放す - 抱きしめる - 抱きしめる","description":"あなたの重荷を軽くし、適切なエネルギーのためのスペースを作るために霊的な棚卸しを行います。","layout_type":"horizontal","positions":[{"index":1,"title":"手放す","question":"もう役に立たず、重くのしかかり、手放す必要がある感情は何ですか?"},{"index":2,"title":"抱きしめる","question":"私が喜んで受け入れ、自分の人生に統合しなければならない、宇宙が提供してくれる贈り物は何でしょうか?"},{"index":3,"title":"ホールド","question":"私が何があっても守り、持ち続け、感謝しなければならない根本的な価値は何ですか？"}]},"ko":{"title":"가자 - 포옹 - 보류","description":"당신의 짐을 가볍게 하고 올바른 에너지를 위한 공간을 만들기 위해 영적인 목록을 작성합니다.","layout_type":"horizontal","positions":[{"index":1,"title":"가자","question":"더 이상 나에게 도움이 되지 않고, 나를 짓누르며, 해방되어야 하는 감정은 무엇입니까?"},{"index":2,"title":"포옹","question":"내가 받아들이고 내 삶에 통합해야 하는 우주는 어떤 선물을 제공합니까?"},{"index":3,"title":"보류","question":"어떤 근본적인 가치를 지키고, 붙잡고, 감사해야 할까요?"}]},"th":{"title":"ปล่อย-โอบ-ยึด","description":"ใช้รายการทางจิตวิญญาณเพื่อแบ่งเบาภาระของคุณและสร้างพื้นที่สำหรับพลังงานที่เหมาะสม","layout_type":"horizontal","positions":[{"index":1,"title":"ปล่อยไป","question":"ความรู้สึกใดที่ไม่ช่วยฉันอีกต่อไป ทำให้ฉันหนักใจ และจำเป็นต้องได้รับการปลดปล่อย?"},{"index":2,"title":"โอบกอด","question":"จักรวาลเสนอของขวัญอะไรให้ฉันต้องเปิดใจรับและบูรณาการเข้ากับชีวิตของฉัน?"},{"index":3,"title":"กดค้างไว้","question":"คุณค่าพื้นฐานอะไรที่ฉันจะต้องปกป้อง ยึดมั่น และรู้สึกขอบคุณไม่ว่าจะเกิดอะไรขึ้น?"}]},"zh-TW":{"title":"放手——擁抱——堅持","description":"進行精神盤點，以減輕你的負擔，為正確的能量騰出空間。","layout_type":"horizontal","positions":[{"index":1,"title":"放手","question":"什麼感覺不再為我服務、讓我感到沉重、需要釋放？"},{"index":2,"title":"擁抱","question":"宇宙提供了什麼禮物，我必須開放地接受並融入我的生活？"},{"index":3,"title":"保持","question":"無論如何，我必須保護、堅持並感激什麼基本價值？"}]},"ru":{"title":"Отпустить - Обнять - Удержать","description":"Проводит духовную инвентаризацию, чтобы облегчить ваше бремя и освободить место для правильных энергий.","layout_type":"horizontal","positions":[{"index":1,"title":"Отпусти","question":"Какое чувство больше не служит мне, тяготит меня и требует освобождения?"},{"index":2,"title":"Обнимать","question":"Какой дар предлагает Вселенная, который я должен принять и интегрировать в свою жизнь?"},{"index":3,"title":"Удерживать","question":"Какую фундаментальную ценность я должен защищать, придерживаться и быть благодарным несмотря ни на что?"}]},"zh-CN":{"title":"放手——拥抱——坚持","description":"进行一次精神盘点，以减轻你的负担，为正确的能量腾出空间。","layout_type":"horizontal","positions":[{"index":1,"title":"放手","question":"什么感觉不再为我服务、让我感到沉重、需要释放？"},{"index":2,"title":"拥抱","question":"宇宙提供了什么礼物，我必须开放地接受并融入我的生活？"},{"index":3,"title":"保持","question":"无论如何，我必须保护、坚持并感激什么基本价值？"}]}}$$::jsonb),
  ('spread_first_day_job', $${"tr":{"title":"Yeni İşte İlk Gün","positions":[{"index":1,"title":"İlk İzlenim","question":"Yeni işimdeki ilk günüm nasıl geçecek?"},{"index":2,"title":"En Büyük Zorluk","question":"Benim için en zor şey ne olacak?"},{"index":3,"title":"Olumlu Sürpriz","question":"Beni olumlu olarak ne şaşırtacak?"},{"index":4,"title":"İş Arkadaşı Karşılaması","question":"İş arkadaşlarım beni nasıl karşılayacak?"},{"index":5,"title":"Dikkat","question":"Bu işte dikkat etmem gereken bir şey var mı?"}],"description":"İlk gündeki zorluklara ve izlenimlere hazırlanmanıza yardımcı olur.","layout_type":"grid"},"es":{"title":"Primer día en un nuevo trabajo","description":"Le ayuda a prepararse para los desafíos e impresiones de su primer día.","layout_type":"grid","positions":[{"index":3,"title":"Sorpresa Positiva","question":"¿Qué me sorprenderá positivamente?"},{"index":2,"title":"El mayor desafío","question":"¿Qué será lo más difícil para mí?"},{"index":4,"title":"Recepción de compañeros de trabajo","question":"¿Cómo me recibirán mis compañeros de trabajo?"},{"index":1,"title":"Primera impresión","question":"¿Cómo será mi primer día en mi nuevo trabajo?"},{"index":5,"title":"Precaución","question":"¿Hay algo a lo que debo prestar atención en este trabajo?"}]},"pt":{"title":"Primeiro dia no novo emprego","description":"Ajuda você a se preparar para desafios e impressões no primeiro dia.","layout_type":"grid","positions":[{"index":3,"title":"Surpresa Positiva","question":"O que me surpreenderá positivamente?"},{"index":2,"title":"Maior desafio","question":"Qual será a coisa mais difícil para mim?"},{"index":4,"title":"Recepção de colegas de trabalho","question":"Como meus colegas de trabalho me receberão?"},{"index":1,"title":"Primeira impressão","question":"Como será meu primeiro dia no meu novo emprego?"},{"index":5,"title":"Cuidado","question":"Há algo que devo prestar atenção neste trabalho?"}]},"fr":{"title":"Premier jour au nouvel emploi","description":