  ('spread_interview_result', $${"tr":{"title":"İş Mülakatı Sonucu","positions":[{"index":1,"title":"İzlenim","question":"Potansiyel işveren üzerinde nasıl bir izlenim bıraktım?"},{"index":2,"title":"Sonuç","question":"Sonuç ne olacak? İşi alacak mıyım?"},{"index":3,"title":"Uygunluk","question":"Bu iş benim için iyi mi?"}],"description":"İş mülakatının sonucunu ve uygunluğunu ortaya koyar.","layout_type":"grid"},"es":{"title":"Resultado de la entrevista de trabajo","description":"Revela el resultado y la idoneidad de la entrevista de trabajo.","layout_type":"grid","positions":[{"index":3,"title":"Idoneidad","question":"¿Este trabajo es bueno para mí?"},{"index":2,"title":"Resultado","question":"¿Cuál será el resultado? ¿Conseguiré el trabajo?"},{"index":1,"title":"impresión","question":"¿Qué impresión dejé en el potencial empleador?"}]},"pt":{"title":"Resultado da entrevista de emprego","description":"Revela o resultado e a adequação da entrevista de emprego.","layout_type":"grid","positions":[{"index":3,"title":"Adequação","question":"Este trabalho é bom para mim?"},{"index":2,"title":"Resultado","question":"Qual será o resultado? Vou conseguir o emprego?"},{"index":1,"title":"Impressão","question":"Que impressão deixei no potencial empregador?"}]},"fr":{"title":"Résultat de l'entretien d'embauche","description":"Révèle le résultat et la pertinence de l’entretien d’embauche.","layout_type":"grid","positions":[{"index":3,"title":"Adéquation","question":"Est-ce que ce travail est bon pour moi ?"},{"index":2,"title":"Résultat","question":"Quel sera le résultat ? Vais-je obtenir le poste ?"},{"index":1,"title":"Impression","question":"Quelle impression ai-je laissée à l’employeur potentiel ?"}]},"de":{"title":"Ergebnis des Vorstellungsgesprächs","description":"Zeigt das Ergebnis und die Eignung des Vorstellungsgesprächs.","layout_type":"grid","positions":[{"index":3,"title":"Eignung","question":"Ist dieser Job gut für mich?"},{"index":2,"title":"Ergebnis","question":"