  ('spread_new_partner', $${"tr":{"title":"Yeni Sevgili","positions":[{"index":1,"title":"Olasılık","question":"6 ay içinde yeni bir sevgiliyle tanışacak mıyım?"},{"index":2,"title":"Kişi","question":"EVET İSE: Ne tür biri olacak? HAYIR İSE: Bu dönemde tek kalmak daha mı iyi?"},{"index":3,"title":"Tatmin","question":"EVET İSE: Tatmin olacak mıyım? HAYIR İSE: Yeni bir sevgiliyle tanışmak için ne yapabilirim?"},{"index":4,"title":"Eylem","question":"EVET İSE: Bu ilişkiyi başarılı kılmak için ne yapabilirim? HAYIR İSE: Daha çekici olmak için kendimde ne değiştirebilirim?"},{"index":5,"title":"Tavsiye","question":"EVET İSE: Bu ilişki için tavsiye. HAYIR İSE: Sevgili aramaya devam etmek için tavsiye."}],"description":"Yeni bir sevgiliyle tanışma şanslarını, özelliklerini ve rehberliğini gösterir.","layout_type":"grid"},"es":{"title":"Nuevo socio","description":"Muestra las posibilidades de conocer una nueva pareja, sus cualidades y orientación.","layout_type":"grid","positions":[{"index":1,"title":"Posibilidad","question":"¿Conoceré una nueva pareja dentro de 6 meses?"},{"index":2,"title":"la persona","question":"EN CASO SÍ: ¿Qué tipo de persona será? SI NO: ¿Es mejor permanecer soltero durante este tiempo?"},{"index":3,"title":"Satisfacción","question":"EN CASO SÍ: ¿Estaré satisfecho? SI NO: ¿Qué puedo hacer para conocer a una nueva pareja?"},{"index":4,"title":"acción","question":"EN CASO SÍ: ¿Qué puedo hacer para que esta relación sea exitosa? SI NO: ¿Qué puedo cambiar de mí para ser más atractivo?"},{"index":5,"title":"Consejo","question":"EN CASO SÍ: Consejos para esta relación. SI NO: Consejo para seguir buscando pareja."}]},"pt":{"title":"Novo parceiro","description":"Mostra as chances de conhecer um novo parceiro, suas qualidades e orientação.","layout_type":"grid","positions":[{"index":1,"title":"Possibilidade","question":"Conhecerei um novo parceiro dentro de 6 meses?"},{"index":2,"title":"A Pessoa","question":"SE SIM: Que tipo de pessoa eles serão? SE NÃO: É m