  ('spread_marriage_proposal', $${"tr":{"title":"Evlilik Teklifi","positions":[{"index":1,"title":"Teklif","question":"Partnerim bana evlilik teklifi edecek mi?"},{"index":2,"title":"Zaman veya Engel","question":"EĞER EVET: Ne zaman? EĞER HAYIR: Onu ne engelliyor?"},{"index":3,"title":"Yer veya Korku","question":"EĞER EVET: Nerede? EĞER HAYIR: Evlilikten korkuyor mu?"},{"index":4,"title":"Aşk veya Değişim","question":"EĞER EVET: Bunu aşktan dolayı mı yapacak? EĞER HAYIR: Bunu değiştirmek için ne yapabilirim?"},{"index":5,"title":"Yakın Gelecek","question":"EĞER EVET: Bu ilişkinin en yakın geleceği ne olacak? EĞER HAYIR: Benim hareketlerimin etkisi ne olur?"}],"description":"Evlilik teklifinin olasılığını, zamanını ve anlamını gösterir.","layout_type":"grid"},"es":{"title":"Propuesta de matrimonio","description":"Muestra la posibilidad, el momento y el significado de una propuesta de matrimonio.","layout_type":"grid","positions":[{"index":1,"title":"Propuesta","question":"¿Mi pareja me propondrá matrimonio?"},{"index":2,"title":"Cuando o Bloquear","question":"EN CASO SÍ: ¿Cuándo? SI NO: ¿Qué los está bloqueando?"},{"index":3,"title":"donde o miedo","question":"EN CASO SÍ: ¿Dónde? SI NO: ¿Tienen miedo al matrimonio?"},{"index":4,"title":"Amar o cambiar","question":"EN CASO SÍ: ¿Lo harán por amor? SI NO: ¿Qué puedo hacer para cambiar esto?"},{"index":5,"title":"Futuro cercano","question":"En caso afirmativo: ¿Cuál será el futuro más cercano de esta relación? SI NO: ¿Cuál será el efecto de mis acciones?"}]},"pt":{"title":"Proposta de casamento","description":"Mostra a possibilidade, o momento e o significado de uma proposta de casamento.","layout_type":"grid","positions":[{"index":1,"title":"Proposta","question":"Meu parceiro me proporá casamento?"},{"index":2,"title":"Quando ou bloquear","question":"SE SIM: Quando? SE NÃO: O que os está bloqueando?"},{"index":3,"title":"Onde ou medo","question":"SE SIM: Onde? SE NÃO: Eles têm medo do casamento?"},{"index":4,"title":"Amar ou mudar","question":"SE SIM: Eles farão isso por amor? SE NÃO: O que posso fazer para mudar isso?"},{"index":5,"title":"Futuro Próximo","question":"SE SIM: Qual será o futuro próximo desta relação? SE NÃO: Qual será o efeito das minhas ações?"}]},"fr":{"title":"Demande en mariage","description":"Montre la possibilité, le moment et la signification d’une demande en mariage.","layout_type":"grid","positions":[{"index":1,"title":"Proposition","question":"Mon partenaire me proposera-t-il le mariage ?"},{"index":2,"title":"Quand ou Bloquer","question":"SI OUI : Quand ? SI NON : Qu’est-ce qui les bloque ?"},{"index":3,"title":"Où ou peur","question":"SI OUI : Où ? SI NON : Ont-ils peur du mariage ?"},{"index":4,"title":"Amour ou changement","question":"SI OUI : Le feront-ils par amour ? SI NON : Que puis-je faire pour changer cela ?"},{"index":5,"title":"Futur proche","question":"SI OUI : Quel sera l’avenir le plus proche de cette relation ? SI NON : Quel sera l’effet de mes actions ?"}]},"de":{"title":"Heiratsantrag","description":"Zeigt die Möglichkeit, den Zeitpunkt und die Bedeutung eines Heiratsantrags.","layout_type":"grid","positions":[{"index":1,"title":"Vorschlag","question":"Wird mein Partner mir einen Heiratsantrag machen?"},{"index":2,"title":"Wann oder Blockieren","question":"WENN JA: Wann? FALLS NEIN: Was blockiert sie?"},{"index":3,"title":"Wo oder Angst","question":"WENN JA: Wo? FALLS NEIN: Haben sie Angst vor der Ehe?"},{"index":4,"title":"Liebe oder Veränderung","question":"WENN JA: Werden sie es aus Liebe tun? FALLS NEIN: Was kann ich tun, um dies zu ändern?"},{"index":5,"title":"Nahe Zukunft","question":"FALLS JA: Wie sieht die nächste Zukunft dieser Beziehung aus? FALLS NEIN: Welche Auswirkungen werden meine Handlungen haben?"}]},"it":{"title":"Proposta di matrimonio","description":"Mostra la possibilità, i tempi e il significato di una proposta di matrimonio.","layout_type":"grid","positions":[{"index":1,"title":"Proposta","question":"Il mio part